import http from 'k6/http';
import { check, sleep, group } from 'k6';
import { Trend, Rate, Counter } from 'k6/metrics';

// Load static config generated by setupBenchmark.js
const config = JSON.parse(open('./config.json'));

// Custom performance metrics per service
const authLatency = new Trend('music_room_auth_duration', true);
const playlistLatency = new Trend('music_room_playlist_duration', true);
const searchLatency = new Trend('music_room_search_duration', true);
const errorRate = new Rate('music_room_errors');
const completedIterations = new Counter('music_room_completed_scenarios');

// K6 Load Stages & Performance Thresholds (SLAs)
export const options = {
  stages: [
    { duration: '10s', target: 20 },  // Ramp-up: 0 à 20 VUs
    { duration: '20s', target: 50 },  // Charge stable: 50 VUs
    { duration: '20s', target: 100 }, // Montée en charge: 100 VUs
    { duration: '20s', target: 150 }, // Pic de stress: 150 VUs
    { duration: '10s', target: 0 },   // Descente: 0 VUs
  ],
  thresholds: {
    'http_req_duration': ['p(95)<500', 'p(99)<1000'], // 95% des requêtes < 500ms
    'http_req_failed': ['rate<0.02'],                  // Moins de 2% d'erreurs HTTP
    'music_room_errors': ['rate<0.02'],
    'music_room_auth_duration': ['p(95)<400'],
    'music_room_playlist_duration': ['p(95)<300'],
    'music_room_search_duration': ['p(95)<600'],
  },
};

const BASE_URL = config.apiUrl || 'http://localhost:3000';
const COMMON_HEADERS = {
  'Content-Type': 'application/json',
  'User-Agent': 'MusicRoom-LoadTest-k6/1.0 (Linux; x86_64; AppVersion: 1.0.0)',
  'x-load-test': 'musicroom-benchmark',
};

const AUTH_HEADERS = {
  ...COMMON_HEADERS,
  'Authorization': `Bearer ${config.accessToken}`,
};

export default function () {
  // Simuler le comportement d'un utilisateur simultané réparti entre les 3 services

  // -------------------------------------------------------------
  // SERVICE 1 : Auth & Profil Utilisateur (Personne 1)
  // -------------------------------------------------------------
  group('Service 1 - Auth & Profil', function () {
    // 1.1 Consultation du profil /me
    const meRes = http.get(`${BASE_URL}/api/users/me`, { headers: AUTH_HEADERS });
    authLatency.add(meRes.timings.duration);
    const meOk = check(meRes, {
      'Service 1: GET /api/users/me status 200': (r) => r.status === 200,
      'Service 1: profil contient email': (r) => r.json('email') === config.email,
    });
    errorRate.add(!meOk);

    // 1.2 Simulation d'une connexion (1 itération sur 5 pour éviter de surcharger bcrypt)
    if (__VU % 5 === 0 && __ITER % 3 === 0) {
      const loginPayload = JSON.stringify({
        email: config.email,
        password: config.password,
      });
      const loginRes = http.post(`${BASE_URL}/api/auth/login`, loginPayload, { headers: COMMON_HEADERS });
      authLatency.add(loginRes.timings.duration);
      const loginOk = check(loginRes, {
        'Service 1: POST /api/auth/login status 200': (r) => r.status === 200,
        'Service 1: login retourne accessToken': (r) => r.json('accessToken') !== undefined,
      });
      errorRate.add(!loginOk);
    }
  });

  sleep(0.3);

  // -------------------------------------------------------------
  // SERVICE 2 : Music Playlist Editor (Personne 3)
  // -------------------------------------------------------------
  group('Service 2 - Music Playlist Editor', function () {
    // 2.1 Liste des playlists publiques
    const listRes = http.get(`${BASE_URL}/api/playlists`, { headers: COMMON_HEADERS });
    playlistLatency.add(listRes.timings.duration);
    const listOk = check(listRes, {
      'Service 2: GET /api/playlists status 200': (r) => r.status === 200,
      'Service 2: contient liste playlists': (r) => r.json('playlists') !== undefined,
    });
    errorRate.add(!listOk);

    // 2.2 Consultation détaillée de la playlist collaborative
    const playlistRes = http.get(`${BASE_URL}/api/playlists/${config.playlistId}`, { headers: AUTH_HEADERS });
    playlistLatency.add(playlistRes.timings.duration);
    const playlistOk = check(playlistRes, {
      'Service 2: GET /api/playlists/:id status 200': (r) => r.status === 200,
      'Service 2: playlist correspondante': (r) => r.json('playlist.id') === config.playlistId,
    });
    errorRate.add(!playlistOk);
  });

  sleep(0.3);

  // -------------------------------------------------------------
  // SERVICE 3 : Music Track Vote & Deezer Search (Personne 2 & 3)
  // -------------------------------------------------------------
  group('Service 3 - Tracks, Salles & Recherche', function () {
    // 3.1 Liste des salles publiques pour le vote (Personne 2)
    const roomsRes = http.get(`${BASE_URL}/api/rooms/public`, { headers: AUTH_HEADERS });
    searchLatency.add(roomsRes.timings.duration);
    const roomsOk = check(roomsRes, {
      'Service 3: GET /api/rooms/public status 200': (r) => r.status === 200,
    });
    errorRate.add(!roomsOk);

    // 3.2 Recherche de titres / Découverte musicale
    const queries = ['daft punk', 'queen', 'the weeknd', 'dua lipa', 'nirvana'];
    const query = queries[__ITER % queries.length];
    const searchRes = http.get(`${BASE_URL}/api/deezer/search?q=${encodeURIComponent(query)}`, { headers: COMMON_HEADERS });
    searchLatency.add(searchRes.timings.duration);
    const searchOk = check(searchRes, {
      'Service 3: GET /api/deezer/search status 200': (r) => r.status === 200,
      'Service 3: résultats présents': (r) => r.json('results') !== undefined,
    });
    errorRate.add(!searchOk);
  });

  completedIterations.add(1);
  sleep(0.5); // Temps de pause utilisateur moyen (pacing)
}
